INSERT INTO process_calculator_mappings (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
SELECT $str$Die Casting$str$, v.name, v.name, NULL, NULL, false, v.display_order, NULL, pt.id
FROM process_taxonomy pt
JOIN (VALUES
  ($str$Cleaning$str$, 2000),
  ($str$Core Refractory Coat$str$, 2001),
  ($str$Coremaking$str$, 2002),
  ($str$Finishing$str$, 2003),
  ($str$Gravity Die Casting$str$, 2004),
  ($str$High Pressure Die Casting$str$, 2005),
  ($str$Melting$str$, 2006),
  ($str$No Cost Feature$str$, 2007),
  ($str$Refractory Coat Air Dry$str$, 2008),
  ($str$Refractory Coat Oven Dry$str$, 2009),
  ($str$Trim$str$, 2010),
  ($str$Visual Inspection$str$, 2011)
) AS v(name, display_order)
  ON pt.process_group = $str$Die Casting$str$ AND pt.process_name = v.name
WHERE NOT EXISTS (
  SELECT 1 FROM process_calculator_mappings m WHERE m.process_group = $str$Die Casting$str$ AND m.operation = v.name
)
ON CONFLICT (process_group, process_route, operation) DO NOTHING;

COMMIT;

NOTIFY pgrst, 'reload schema';

